WITH with_windows AS (SELECT id, store_id, sale_date, units, revenue, LEAD(revenue) OVER w_recent AS next_revenue, LAG(units) OVER w_recent AS prev_units, LEAD(units) OVER w_recent AS next_units, ROW_NUMBER() OVER w_recent AS seq_no FROM store_sales WINDOW w_recent AS (PARTITION BY store_id ORDER BY revenue ASC, id ASC)), joined AS (SELECT a.*, b.sqft, b.region, b.opened_date FROM with_windows a LEFT JOIN stores b ON a.store_id = b.id), joined_store_sales AS (SELECT a.id, a.store_id, a.units, a.next_revenue, a.prev_units, a.next_units, a.sqft, p.sqft AS store_sqft FROM joined a LEFT JOIN stores p ON a.store_id = p.id WHERE p.city = 'Singapore'), with_dims AS (SELECT e.id, e.store_id, e.next_revenue, e.prev_units, e.next_units, e.sqft, d.region FROM joined_store_sales e LEFT JOIN stores d ON e.store_id = d.id), summary AS (SELECT region, COUNT(*) FILTER (WHERE region = 'North') AS north_rows, COUNT(*) FILTER (WHERE region = 'West') AS west_rows, ROUND(SUM(next_units) / NULLIF(COUNT(CASE WHEN region = 'North' THEN 1 END), 0), 2) AS next_units_per_north, APPROX_PERCENTILE(next_units, 0.95) AS next_units_p95 FROM with_dims GROUP BY 1) SELECT region, north_rows, next_units_per_north, next_units_p95 FROM summary ORDER BY region ASC, north_rows ASC;
